import { homedir } from 'node:os';
import path from 'node:path';
import { BRAND } from '../brand.ts';
import type { IndexEntry, IndexSnapshot, IndexStatus } from './snapshot.ts';

// The page and its plain-text twin. Static HTML regenerated by the tool;
// the page reloads itself so a browser tab left open follows along.

const STATUS_LABELS: Record<IndexStatus, string> = {
  running: 'Running',
  partial: 'Partial',
  stopped: 'Stopped',
  missing: 'Missing',
  unknown: 'Unknown'
};

export function escapeHtml(value: string): string {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

/** `/Users/me/dev/x` → `~/dev/x`; paths outside the home are left alone. */
export function compactPath(target: string, home = homedir()): string {
  const relative = path.relative(home, target);
  return relative !== '' && !relative.startsWith('..') && !path.isAbsolute(relative)
    ? path.join('~', relative)
    : target;
}

function groupByProject(entries: readonly IndexEntry[]): Map<string, IndexEntry[]> {
  const groups = new Map<string, IndexEntry[]>();
  for (const entry of entries) {
    const key = `${entry.project} · ${entry.domain}`;
    groups.set(key, [...(groups.get(key) ?? []), entry]);
  }
  return groups;
}

function renderRow(entry: IndexEntry): string {
  const checkout = entry.root
    ? `<span class="path" title="${escapeHtml(entry.root)}">${escapeHtml(compactPath(entry.root))}</span>`
    : '<span class="muted">—</span>';
  const services = entry.services.length === 0
    ? '<span class="muted">—</span>'
    : `<ul>${entry.services.map((service) => {
      const contents = `<span class="service-label">${escapeHtml(service.label)}</span><span class="service-purpose">${escapeHtml(service.purpose)}</span>`;
      return service.available
        ? `<li><a class="service-link" href="${escapeHtml(service.url)}" target="${escapeHtml(`${entry.host}-${service.name}`)}" title="${escapeHtml(service.url)}">${contents}</a></li>`
        : `<li><span class="service-link service-disabled" title="${escapeHtml(service.url)}" aria-disabled="true">${contents}</span></li>`;
    }).join('')}</ul>`;
  const guidance = entry.status === 'missing'
    ? `<div class="guidance">Checkout gone — <code>${escapeHtml(BRAND.name)} worktree remove ${escapeHtml(entry.slug)}</code></div>`
    : '';
  return `<tr>
      <td><strong>${escapeHtml(entry.branch ?? '(detached)')}</strong></td>
      <td><code>${escapeHtml(entry.host)}</code></td>
      <td>${checkout}</td>
      <td><span class="status status-${entry.status}">${STATUS_LABELS[entry.status]}</span>${guidance}</td>
      <td class="services">${services}</td>
    </tr>`;
}

export function renderIndexHtml(snapshot: IndexSnapshot): string {
  const groups = [...groupByProject(snapshot.entries)].map(([title, entries]) => `
    <section>
      <h2>${escapeHtml(title)}</h2>
      <div class="table-wrap">
        <table>
          <thead><tr><th>Branch</th><th>Host</th><th>Checkout</th><th>Status</th><th>Services</th></tr></thead>
          <tbody>${entries.map(renderRow).join('\n')}</tbody>
        </table>
      </div>
    </section>`).join('\n');
  const body = groups || `<p class="empty">No checkouts have been indexed yet. Run <code>${escapeHtml(BRAND.name)} up</code> in a worktree.</p>`;
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta http-equiv="refresh" content="15">
  <title>Checkouts</title>
  <style>
    :root { color-scheme: light dark; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif; }
    * { box-sizing: border-box; }
    body { margin: 0; min-width: 320px; color: #18212b; background: #f4f6f8; }
    header { display: flex; align-items: end; justify-content: space-between; gap: 24px; padding: 28px 32px 20px; border-bottom: 1px solid #cbd2d9; background: #fff; }
    h1 { margin: 0; font-size: 24px; line-height: 1.2; }
    h2 { margin: 28px 0 10px; font-size: 15px; color: #52606d; }
    .updated { margin: 0; color: #52606d; font-size: 13px; white-space: nowrap; }
    main { padding: 4px 32px 32px; }
    .table-wrap { overflow-x: auto; border: 1px solid #cbd2d9; border-radius: 6px; background: #fff; }
    table { width: 100%; min-width: 960px; border-collapse: collapse; table-layout: fixed; }
    th { padding: 10px 14px; color: #52606d; background: #eef1f4; font-size: 12px; font-weight: 700; text-align: left; text-transform: uppercase; }
    td { padding: 14px; border-top: 1px solid #e4e7eb; font-size: 14px; vertical-align: top; }
    th:nth-child(1) { width: 18%; } th:nth-child(2) { width: 22%; } th:nth-child(3) { width: 20%; } th:nth-child(4) { width: 12%; } th:nth-child(5) { width: 28%; }
    code { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: 12px; }
    .path { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .muted { color: #7b8794; }
    .services ul { margin: 0; padding: 0; list-style: none; }
    .service-link { display: grid; grid-template-columns: minmax(110px, 0.8fr) minmax(150px, 1.6fr); gap: 8px; margin: 0 -6px; padding: 4px 6px; border-radius: 4px; color: inherit; line-height: 1.35; text-decoration: none; }
    a.service-link:hover { background: #eef6f9; }
    .service-label { color: #075985; font-weight: 650; text-decoration: underline; text-underline-offset: 3px; }
    .service-purpose { color: #52606d; font-size: 12px; }
    .service-disabled .service-label, .service-disabled .service-purpose { color: #7b8794; text-decoration: none; }
    .status { display: inline-block; min-width: 68px; padding: 3px 8px; border-radius: 999px; font-size: 12px; font-weight: 700; text-align: center; }
    .status-running { color: #14532d; background: #dcfce7; }
    .status-partial { color: #713f12; background: #fef3c7; }
    .status-stopped { color: #374151; background: #e5e7eb; }
    .status-missing { color: #7f1d1d; background: #fee2e2; }
    .status-unknown { color: #4c1d95; background: #ede9fe; }
    .guidance { margin-top: 7px; color: #7f1d1d; font-size: 11px; }
    .empty { padding: 36px; color: #52606d; text-align: center; }
    @media (prefers-color-scheme: dark) {
      body { color: #e5e7eb; background: #111827; }
      header, .table-wrap { background: #1f2937; border-color: #374151; }
      th { color: #9ca3af; background: #111827; }
      td { border-color: #374151; }
      h2, .updated, .service-purpose { color: #9ca3af; }
      .service-label { color: #7dd3fc; }
      a.service-link:hover { background: #0c4a6e; }
    }
  </style>
</head>
<body>
  <header>
    <h1>Checkouts</h1>
    <p class="updated">Updated <time datetime="${escapeHtml(snapshot.generatedAt)}">${escapeHtml(snapshot.generatedAt)}</time></p>
  </header>
  <main>${body}
  </main>
</body>
</html>
`;
}

export function formatIndexText(snapshot: IndexSnapshot, url: string): string {
  const groups = [...groupByProject(snapshot.entries)].map(([title, entries]) => {
    const rows = entries.map((entry) => {
      const services = entry.services.map((service) =>
        `    ${service.label.padEnd(18)} ${service.url}${service.available ? '' : '  (unavailable)'}`
      ).join('\n');
      const lines = [
        `  ${entry.branch ?? '(detached)'}  [${STATUS_LABELS[entry.status]}]`,
        `    host      ${entry.host}`,
        `    checkout  ${entry.root ? compactPath(entry.root) : '-'}`
      ];
      return [...lines, services].filter(Boolean).join('\n');
    }).join('\n\n');
    return `${title}\n${rows}`;
  }).join('\n\n');
  return `Checkout index  ${url}\nUpdated         ${snapshot.generatedAt}\n\n${groups || 'No checkouts have been indexed yet.'}`;
}
